WITH source_dialogues AS (
  SELECT * FROM jsonb_to_recordset($9::jsonb) AS d(dialogue_id text,scene_id text,sequence_number int)
), source_shots AS (
  SELECT * FROM jsonb_to_recordset($10::jsonb) AS s(shot_id text,scene_id text,shot_order int,bgm_hint text,sound_effect_hint text,atmosphere text)
), exact_audio AS (
  SELECT a.* FROM drama.dialogue_audio a JOIN source_dialogues d USING(dialogue_id)
  WHERE a.project_id=$1 AND a.episode_id=$2 AND a.generation_version=$4
), stats AS (
  SELECT count(*)::int total_count,count(a.*) FILTER(WHERE a.status='succeeded' AND a.auto_qc_status IN('passed','warning'))::int success_count,
    count(a.*) FILTER(WHERE a.status IN('failed','timeout') OR a.auto_qc_status='failed')::int failed_count,
    count(*) FILTER(WHERE a.dialogue_audio_id IS NULL OR a.status IN('pending','generating','processing') OR(a.status='succeeded' AND a.auto_qc_status='pending'))::int processing_count,
    coalesce(sum(a.actual_duration_ms) FILTER(WHERE a.status='succeeded'),0)::int duration_ms
  FROM source_dialogues d LEFT JOIN exact_audio a USING(dialogue_id)
), ids AS (
  SELECT coalesce(jsonb_agg(a.dialogue_audio_id ORDER BY d.sequence_number) FILTER(WHERE a.status='succeeded'),'[]'::jsonb) audio_ids
  FROM source_dialogues d LEFT JOIN exact_audio a USING(dialogue_id)
), cues AS (
  SELECT coalesce(jsonb_agg(jsonb_build_object('cue_id','bgm_'||shot_id,'scene_id',scene_id,'shot_id',shot_id,'start_hint','shot_'||shot_order,'end_hint','','mood',bgm_hint,'intensity',1,'music_style',bgm_hint,'duck_under_dialogue',true)) FILTER(WHERE coalesce(bgm_hint,'')<>''),'[]'::jsonb) bgm,
    coalesce(jsonb_agg(jsonb_build_object('cue_id','sfx_'||shot_id,'shot_id',shot_id,'timing_hint','shot_'||shot_order,'description',sound_effect_hint,'priority','normal')) FILTER(WHERE coalesce(sound_effect_hint,'')<>''),'[]'::jsonb) sfx,
    coalesce(jsonb_agg(jsonb_build_object('cue_id','amb_'||shot_id,'shot_id',shot_id,'description',atmosphere)) FILTER(WHERE coalesce(atmosphere,'')<>''),'[]'::jsonb) ambience FROM source_shots
), plan AS (
  INSERT INTO drama.episode_audio_plans(audio_plan_id,project_id,episode_id,script_id,version,narrator_voice_profile_id,dialogue_audio_ids,bgm_cues,sound_effect_cues,ambience_cues,subtitle_config,estimated_duration_ms,status,review_status)
  SELECT $3,$1,$2,$8,$4,NULLIF($11,''),ids.audio_ids,cues.bgm,cues.sfx,cues.ambience,$5::jsonb,stats.duration_ms,
    CASE WHEN stats.failed_count>0 THEN'failed' WHEN stats.processing_count>0 OR stats.success_count<stats.total_count THEN'generating' ELSE'ready' END,'pending'
  FROM stats CROSS JOIN ids CROSS JOIN cues
  ON CONFLICT(episode_id,version) DO UPDATE SET narrator_voice_profile_id=excluded.narrator_voice_profile_id,dialogue_audio_ids=excluded.dialogue_audio_ids,bgm_cues=excluded.bgm_cues,sound_effect_cues=excluded.sound_effect_cues,ambience_cues=excluded.ambience_cues,subtitle_config=excluded.subtitle_config,estimated_duration_ms=excluded.estimated_duration_ms,status=excluded.status RETURNING *
), flags AS (
  SELECT (SELECT status='ready' FROM plan) audio_ready,(SELECT failed_count>0 FROM stats) audio_failed,($12::boolean AND (SELECT status='ready' FROM plan)) full_done
), next_state AS (
  SELECT p.project_id,CASE WHEN f.full_done THEN'stage_4_completed' WHEN f.audio_failed THEN'stage_4_failed' WHEN p.current_stage IN('video_processing','shot_video_review','shot_videos_generated','shot_videos_approved') THEN p.current_stage WHEN f.audio_ready THEN'audio_ready' ELSE'audio_processing' END next_stage,
    CASE WHEN f.full_done THEN'stage_4_completed' WHEN f.audio_failed THEN'stage_4_failed' WHEN p.current_stage IN('video_processing','shot_video_review','shot_videos_generated','shot_videos_approved') THEN p.status WHEN f.audio_ready THEN'audio_ready' ELSE'audio_processing' END next_status
  FROM drama.projects p CROSS JOIN flags f WHERE p.project_id=$1
), project_patch AS (
  UPDATE drama.projects p SET current_stage=n.next_stage,status=n.next_status,error_message=CASE WHEN n.next_stage='stage_4_failed' THEN'one or more dialogue audio tasks failed; fix TTS provider/configuration and resume' WHEN n.next_stage IN('stage_4_completed','audio_ready') THEN NULL ELSE p.error_message END
  FROM next_state n WHERE p.project_id=n.project_id
), done AS (
  UPDATE drama.workflow_tasks SET status=CASE WHEN(SELECT audio_failed FROM flags)THEN'failed'ELSE'completed'END,completed_at=now(),error_code=CASE WHEN(SELECT audio_failed FROM flags)THEN'TTS_TASKS_FAILED'ELSE NULL END,error_message=CASE WHEN(SELECT audio_failed FROM flags)THEN'one or more dialogue audio tasks failed; fix TTS provider/configuration and resume'ELSE NULL END,
    output_data=jsonb_build_object('success',NOT(SELECT audio_failed FROM flags),'project_id',$1,'trace_id',$6::text,'stage','voice_audio','status',CASE WHEN(SELECT full_done FROM flags)THEN'stage_4_completed'WHEN(SELECT audio_failed FROM flags)THEN'stage_4_failed'WHEN(SELECT audio_ready FROM flags)THEN'audio_ready'ELSE'audio_processing'END,'data_ref',jsonb_build_object('entity_type','episode_audio_plan','entity_id',$3,'episode_id',$2,'script_id',$8),'metrics',jsonb_build_object('total_dialogues',(SELECT total_count FROM stats),'succeeded',(SELECT success_count FROM stats),'failed',(SELECT failed_count FROM stats),'processing',(SELECT processing_count FROM stats),'duration_ms',(SELECT duration_ms FROM stats)),'error',CASE WHEN(SELECT audio_failed FROM flags)THEN jsonb_build_object('code','TTS_TASKS_FAILED','message','one or more dialogue audio tasks failed; fix TTS provider/configuration and resume','retryable',true)ELSE NULL END)
  WHERE idempotency_key=$7 RETURNING output_data
) SELECT output_data FROM done;

