const crypto=require('crypto');
const i=$json||{},raw=i.payload&&typeof i.payload==='object'&&!Array.isArray(i.payload)?i.payload:{};
const bool=(v,d=false)=>v===undefined||v===null||v===''?d:(v===true||String(v).toLowerCase()==='true'||String(v)==='1');
const cleanId=(v,name,required=true)=>{const s=v==null?'':String(v).trim();if(!s&&!required)return null;if(!s||s.length>160||!/^[A-Za-z0-9_-]+$/.test(s))throw new Error('INVALID_'+name.toUpperCase());return s};
const secret=/authorization|api[-_]?key|access[-_]?token|refresh[-_]?token|secret|password|cookie|signature/i;
const scrub=(v,depth=0)=>{if(depth>8)return'[depth-limited]';if(Array.isArray(v))return v.slice(0,200).map(x=>scrub(x,depth+1));if(v&&typeof v==='object'){const o={};for(const[k,x]of Object.entries(v)){if(secret.test(k))continue;if(/base64|binary/i.test(k)&&x)throw new Error('BASE64_MEDIA_NOT_ALLOWED');o[k]=scrub(x,depth+1)}return o}if(typeof v==='string'){if(/^data:[^,]*;base64,/i.test(v)||v.length>250000)throw new Error('BASE64_MEDIA_NOT_ALLOWED');return v.length>20000?v.slice(0,20000)+'[truncated]':v}return v};
const p=scrub({...raw});
for(const k of ['master_id','qc_report_id','metadata_id','review_status','reviewer_comment','rejection_scope','rejection_entity_ids','rejection_reason','revision_instruction','override_blocking_issues','override_reason','platform','provider','scheduled_at','visibility','selected_title','description','hashtags','selected_cover_url','cover_asset_id'])if(i[k]!==undefined&&p[k]===undefined)p[k]=scrub(i[k]);
const project_id=cleanId(i.project_id||p.project_id,'project_id'),episode_id=cleanId(i.episode_id||p.episode_id,'episode_id');
const rawAction=String(i.action||p.action||'run').trim().toLowerCase();
const allowed=['run','retry','regenerate','review','resume','cancel','render','qc','publish','schedule','generate_package','final_review','publication_metadata','publication_metadata_review'];
if(!allowed.includes(rawAction))throw new Error('BUSINESS_VALIDATION_FAILED: unsupported action '+rawAction);
const entity=String(p.entity_type||p.review_type||p.target||'').toLowerCase(),checkpoint=String(p.checkpoint||p.target_stage||'').toLowerCase();
let route;
if(rawAction==='final_review')route='final_review';
