   WHERE qc_job_id=$1 RETURNING *
),r AS(
  INSERT INTO drama.qc_reports(qc_report_id,qc_job_id,project_id,episode_id,master_id,technical_report,subtitle_report,content_report,compliance_report,overall_score,severity,blocking_issues,warnings,recommended_actions,routing_decisions,status,version)
  SELECT $2,$1,$3,$4,$5,$6::jsonb,$7::jsonb,$8::jsonb,$9::jsonb,$10,$11,$12::jsonb,$13::jsonb,$14::jsonb,$15::jsonb,'completed',$16 FROM j
  ON CONFLICT(master_id,version) DO UPDATE SET qc_job_id=excluded.qc_job_id,technical_report=excluded.technical_report,subtitle_report=excluded.subtitle_report,content_report=excluded.content_report,compliance_report=excluded.compliance_report,overall_score=excluded.overall_score,severity=excluded.severity,blocking_issues=excluded.blocking_issues,warnings=excluded.warnings,recommended_actions=excluded.recommended_actions,routing_decisions=excluded.routing_decisions,status='completed'
  RETURNING *
),p AS(
