  INSERT INTO drama.workflow_notifications(notification_id,project_id,episode_id,notification_type,severity,title,message,data,status)
  SELECT 'notify_'||$2,$3,$4,'final_review_required',CASE WHEN $11 IN('blocked','failed') THEN 'error' WHEN $11='warning' THEN 'warning' ELSE 'info' END,'Final review required','QC completed; human final review is required before publication.',jsonb_build_object('master_id',$5,'qc_report_id',$2,'severity',$11,'routing_decisions',$15::jsonb),'pending'
  WHERE EXISTS(SELECT 1 FROM r) ON CONFLICT(notification_id) DO NOTHING
)
